var extractTokenFromHeader = (authorizationHeader) => {
  if (!authorizationHeader) return null;
  const trimmedHeader = authorizationHeader.trim();
  if (!trimmedHeader) return null;
  const bearerMatch = trimmedHeader.match(/^Bearer\s+(.+)$/i);
  const token = bearerMatch?.[1] ?? trimmedHeader;
  return token.replace(/^['\"]|['\"]$/g, "").trim();
};
var auth = (...roles) => {
  return async (req, res, next) => {
    try {
      const token = extractTokenFromHeader(req.headers.authorization);
      if (!token) {
        return res.status(401).json({ message: "Unauthorized: token is missing" });
      }
      if (!secret) {
        return res.status(500).json({ message: "Server auth configuration error" });
      }
      const decoded = jwt2.verify(token, secret);
      const userData = await prisma.user.findUnique({
        where: {
          email: decoded.email
        }
      });
      if (!userData) {
        return res.status(404).json({ message: "User Not Found" });
      }
      if (userData.status !== "ACTIVE") {
        return res.status(403).json({ message: "Account not active" });
      }
      if (roles.length && !roles.includes(decoded.role)) {
        return res.status(403).json({ message: "Forbidden" });
      }
      req.user = decoded;
      return next();
    } catch (error) {
      return next(error);
    }
  };
};
