var deleteEvent = async (id, adminId) => {
  const event = await prisma.event.findUnique({ where: { id } });
  if (!event) throw new AppError(404, "Event not found");
  await prisma.$transaction(async (tx) => {
    await tx.participant.deleteMany({ where: { eventId: id } });
    await tx.invitation.deleteMany({ where: { eventId: id } });
    await tx.payment.deleteMany({ where: { eventId: id } });
    await tx.review.deleteMany({ where: { eventId: id } });
    await tx.event.delete({ where: { id } });
    await tx.activityLog.create({
      data: { action: "DELETE_EVENT", targetId: id, adminId }
    });
  });
  return true;
};
var toggleEventFeature = async (id, isFeatured) => {
  const event = await prisma.event.findUnique({ where: { id } });
  if (!event) throw new AppError(404, "Event not found");
  return await prisma.event.update({
    where: { id },
    data: { isFeatured }
  });
};
var updateEventStatus = async (id, eventStatus) => {
  const allowedStatuses = ["AVAILABLE", "COMPLETED", "CANCELLED", "EXPIRED"];
  if (!allowedStatuses.includes(eventStatus)) {
    throw new AppError(
      400,
      `Invalid eventStatus. Allowed values: ${allowedStatuses.join(", ")}`
    );
  }
  const event = await prisma.event.findUnique({ where: { id } });
  if (!event) throw new AppError(404, "Event not found");
  return await prisma.event.update({
    where: { id },
    data: { eventStatus }
  });
};
var deleteReview = async (id, adminId) => {
  const review = await prisma.review.findUnique({ where: { id } });
  if (!review) throw new AppError(404, "Review not found");
  await prisma.review.delete({ where: { id } });
  const result = await prisma.review.aggregate({
    _avg: { rating: true },
    _count: { id: true },
    where: { eventId: review.eventId }
  });
  await prisma.event.update({
    where: { id: review.eventId },
    data: {
      averageRating: result._avg.rating || 0,
      reviewCount: result._count.id || 0
    }
  });
  await prisma.activityLog.create({
    data: { action: "DELETE_REVIEW", targetId: id, adminId }
  });
  return true;
};
var getDashboardAnalytics = async () => {
  const totalUsers = await prisma.user.count();
  const totalEvents = await prisma.event.count();
  const totalReviews = await prisma.review.count();
  const totalParticipations = await prisma.participant.count();
  const paymentAgg = await prisma.payment.aggregate({
    _sum: { amount: true },
    where: { status: "PAID" }
  });
  return {
    totalUsers,
    totalEvents,
    totalReviews,
    totalParticipations,
    totalRevenue: paymentAgg._sum.amount || 0
  };
};
var getActivityLogs = async (pagination) => {
  const { page, limit } = pagination;
  const logs = await prisma.activityLog.findMany({
    skip: (page - 1) * limit,
    take: limit,
    orderBy: { createdAt: "desc" },
    include: { admin: { select: { id: true, name: true, email: true } } }
  });
  const total = await prisma.activityLog.count();
  return { logs, total, page, limit };
};
var getAllReports = async (filters, pagination) => {
  const { page, limit } = pagination;
  const { status, targetType } = filters;
  const whereClause = {};
  if (status) whereClause.status = status;
  if (targetType) whereClause.targetType = targetType;
  const reports = await prisma.report.findMany({
    where: whereClause,
    skip: (page - 1) * limit,
    take: limit,
    orderBy: { createdAt: "desc" },
    include: { reporter: { select: { id: true, name: true, email: true } } }
  });
  const total = await prisma.report.count({ where: whereClause });
  return { reports, total, page, limit };
};
var updateReportStatus = async (id, status) => {
  const report = await prisma.report.findUnique({ where: { id } });
  if (!report) throw new AppError(404, "Report not found");
  return await prisma.report.update({
    where: { id },
    data: { status }
  });
};
