var setAuthCookie = (res, token) => {
  res.cookie("token", token, {
    secure: false,
    //in production it will be true
    httpOnly: true,
    sameSite: "strict"
  });
};
var createUser = async (req, res) => {
  try {
    const result = await AuthService.createUserIntoDB(req.body);
    res.status(201).json({
      success: true,
      data: result,
      message: "User Registered Successfully"
    });
  } catch (error) {
    console.log(error);
    res.status(500).json({
      success: false,
      message: error.message
    });
  }
};
var loginUser = (req, res) => {
  passport2.authenticate(
    "local",
    { session: false },
    (error, user, info) => {
      if (error) {
        return res.status(500).json({
          success: false,
          message: error.message
        });
      }
      if (!user) {
        return res.status(401).json({
          success: false,
          message: info?.message || "Invalid email or password"
        });
      }
      const result = AuthService.issueAuthForUser(user);
      setAuthCookie(res, result.token);
      return res.status(200).json({
        success: true,
        data: result,
        message: "User Logged in Successfully"
      });
    }
  )(req, res);
};
var facebookSocialLogin = (req, res) => {
  req.body.access_token = req.body.access_token || req.body.accessToken;
  passport2.authenticate(
    "facebook-token",
    { session: false },
    (error, user, info) => {
      if (error) {
        return res.status(500).json({
          success: false,
          message: error.message
        });
      }
      if (!user) {
        return res.status(401).json({
          success: false,
          message: info?.message || "Facebook authentication failed"
        });
      }
      const result = AuthService.issueAuthForUser(user);
      setAuthCookie(res, result.token);
      return res.status(200).json({
        success: true,
        data: result,
        message: "Facebook social login successful"
      });
    }
  )(req, res);
};
